import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

export interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. Por defecto, `new Date()`. */
  now?: Date | undefined;
  /** Cableada por el shell para MSG-02, que no está en el alcance: se recibe y se ignora. */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte un error desconocido en texto que enseña el fallo de verdad.
 *
 * F-128: PostgREST rechaza con un objeto plano `{ code, message }`, así que
 * `String(e)` daría `[object Object]`; se extraen `code`, `message`, `details`
 * y `hint` cuando existen y se muestran junto a la frase para humanos.
 */
function errorText(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === 'string') return e;
  if (typeof e === 'object' && e !== null) {
    const rec = e as {
      code?: unknown;
      message?: unknown;
      details?: unknown;
      hint?: unknown;
    };
    const parts = [rec.code, rec.message, rec.details, rec.hint]
      .filter((v): v is string | number => typeof v === 'string' || typeof v === 'number')
      .map((v) => String(v));
    if (parts.length > 0) return parts.join(' · ');
  }
  try {
    return JSON.stringify(e);
  } catch {
    return String(e);
  }
}

/**
 * Ventana de números de página. Con pocas páginas se muestran todas; con muchas,
 * la actual con su vecindario más los extremos.
 */
function pageNumbers(current: number, total: number): Array<number | '…'> {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  const wanted = new Set<number>([1, total, current - 1, current, current + 1]);
  const ordered = [...wanted].filter((n) => n >= 1 && n <= total).sort((a, b) => a - b);
  const out: Array<number | '…'> = [];
  let prev = 0;
  ordered.forEach((n) => {
    if (n - prev > 1) out.push('…');
    out.push(n);
    prev = n;
  });
  return out;
}

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla completa del panel de contenido: posee el estado de búsqueda y de
 * página, carga `fetchThreadPage` con `profile.orgId` y delega el dibujo de las
 * filas en `ThreadList`.
 */
export function Messages({ profile, now }: MessagesProps) {
  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const pages = pageCount(total);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((res) => {
        if (cancelled) return;
        setThreads(res.threads);
        setTotal(res.total);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setThreads([]);
        setTotal(0);
        setError(errorText(err));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  function submitSearch(e: FormEvent) {
    e.preventDefault();
    setSearch(draft);
    setPage(1);
  }

  function goTo(nextPage: number) {
    setPage(Math.min(Math.max(nextPage, 1), pages));
  }

  return (
    <>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de
        extremo a extremo.
      </p>

      {/* E2EE informativo sin botón: en el MVP no hay passphrase ni recuperación. */}
      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>
          E2EE activo · claves en memoria de sesión · contenido descifrado localmente
        </span>
      </div>

      <div className={styles.actionsBar}>
        <form className={styles.searchForm} onSubmit={submitSearch}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            aria-label="Buscar por nombre de organización"
          />
        </form>

        <button type="button" className={styles.btnPrimary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.scopeNote} data-testid="directorio-scope">
          Abre DIR-01, que queda fuera del MVP.
        </span>

        {!error && (
          <span className={styles.threadCount} data-testid="pag-info">
            {total} {total === 1 ? 'hilo' : 'hilos'} · Página {page} de {pages}
          </span>
        )}
      </div>

      {loading ? (
        <div className={styles.statusNote} role="status">
          Cargando hilos…
        </div>
      ) : error ? (
        <div className={styles.errorBox} role="alert">
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {error}</span>
        </div>
      ) : (
        <>
          {/* MSG-02 no está en el alcance: abrir un hilo no lleva a ninguna parte. */}
          <ThreadList threads={threads} now={now} onOpen={() => {}} />
          {total > 0 && (
            <div className={styles.pagination}>
              <button
                type="button"
                className={`${styles.pageButton} ${styles.pageCtrl}`}
                onClick={() => goTo(page - 1)}
                disabled={page <= 1}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {pageNumbers(page, pages).map((entry, index) =>
                entry === '…' ? (
                  <span key={`gap-${index}`} className={styles.pageGap} aria-hidden="true">
                    …
                  </span>
                ) : (
                  <button
                    key={entry}
                    type="button"
                    className={`${styles.pageButton} ${
                      entry === page ? styles.pageActive : ''
                    }`}
                    onClick={() => goTo(entry)}
                    disabled={entry === page}
                    aria-current={entry === page ? 'page' : undefined}
                  >
                    {entry}
                  </button>
                ),
              )}
              <button
                type="button"
                className={`${styles.pageButton} ${styles.pageCtrl}`}
                onClick={() => goTo(page + 1)}
                disabled={page >= pages}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </div>
          )}
        </>
      )}
    </>
  );
}

