import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * Mapeo tono → clase CSS.
 *
 * F-143: con `noUncheckedIndexedAccess` activo, cada propiedad de `styles` se
 * tipa como `string | undefined`; el diccionario lo declara así y el hueco se
 * resuelve en el único punto de consumo con `?? ''`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

/**
 * MSG-01 · Lista de hilos (presentacional).
 *
 * Pinta las filas en el orden exacto en que las recibe — el orden viene del
 * servidor — y avisa con el ID del hilo al abrirlo. No carga datos ni pagina.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // F-128 / F-141: con el array vacío no queda ningún `<li>` en el documento;
    // el estado vacío vive fuera de cualquier `<ul>`.
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        <button type="button" className={styles.btnPrimary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Ir al Directorio
        </button>
        <span className={styles.emptyReason}>
          El Directorio queda fuera del MVP en esta versión.
        </span>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        // F-131: el `<li>` conserva su rol implícito `listitem`; la acción vive
        // en un `<button>` DENTRO de la fila, nunca en un role encima del li.
        <li key={thread.id} className={styles.item}>
          <button
            type="button"
            className={styles.rowButton}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.rowTop}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
              ) : null}
            </span>
            <span className={styles.timeCell}>
              <span className={styles.time}>{relativeTime(thread.lastItemAt, now)}</span>
            </span>
            <span className={styles.rowBottom}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span
                className={`${styles.stateBadge} ${
                  TONE_CLASS[stateTone(thread.state)] ?? ''
                }`}
              >
                {thread.state}
              </span>
            </span>
            <span className={styles.tail} aria-hidden="true" />
          </button>
        </li>
      ))}
    </ul>
  );
}
